import { useEffect, useState } from "react";

export default function Reviews() {
  const [reviews, setReviews] = useState([]);

  useEffect(() => {
    fetch("http://localhost:5001/admin/reviews", {
      headers: {
        Authorization: "Bearer " + localStorage.getItem("adminToken"),
      },
    })
      .then((res) => res.json())
      .then(setReviews);
  }, []);

  const update = (id, status) => {
    fetch(`http://localhost:5001/admin/reviews/${id}`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        Authorization: "Bearer " + localStorage.getItem("adminToken"),
      },
      body: JSON.stringify({ status }),
    });
  };

  return (
    <div className="space-y-6">
      {reviews.map((r) => (
        <div
          key={r.id}
          className="border border-white/10 rounded-xl p-6"
        >
          <h3 className="text-lg font-bold text-[#e9b21a]">
            {r.name} ({r.rating}★)
          </h3>
          <p className="text-gray-400 mt-2">{r.message}</p>

          <div className="mt-4 flex gap-4">
            <button
              onClick={() => update(r.id, "Active")}
              className="px-4 py-2 bg-[#e9b21a] text-black rounded"
            >
              Approve
            </button>
            <button
              onClick={() => update(r.id, "Hidden")}
              className="px-4 py-2 border border-white/20 rounded"
            >
              Hide
            </button>
          </div>
        </div>
      ))}
    </div>
  );
}
